final url2 = await timedOut.start(timeout: const Duration(milliseconds: 50));
final sw = Stopwatch()..start();
expect(await timedOut.waitForCode(), isNull);
expect(sw.elapsed, greaterThan(const Duration(milliseconds: 40)));
