library;

import 'dart:async';
import 'dart:convert';
import 'dart:io';

import 'package:flutter_agent_harness/src/cli/openrouter_oauth_server.dart';
import 'package:flutter_agent_harness/src/providers/openrouter_oauth.dart';
import 'package:test/test.dart';

void main() {
  group('OpenRouterOAuthLocalCallbackServer', () {
    test('binds to 127.0.0.1 on an ephemeral port', () async {
      final server = OpenRouterOAuthLocalCallbackServer();
      final url = await server.start(timeout: const Duration(seconds: 1));
      expect(url, startsWith('http://127.0.0.1:'));
      expect(url, endsWith('/'));
      await server.close();
    });
  Future<String> start({Duration timeout = const Duration(minutes: 5)}) async {
    await _closeExisting();
    _codeCompleter = Completer<String?>();

    _server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
    final server = _server!;
    final url = 'http://127.0.0.1:${server.port}/';

    _timeoutTimer = Timer(timeout, () {
      if (_codeCompleter case final c? when !c.isCompleted) {
        c.complete(null);
      }
      unawaited(close());
    });

    server.listen(_handleRequest, onDone: _onDone);

    return url;
  }

  void _handleRequest(HttpRequest request) {
    final code = request.uri.queryParameters['code'];
    final error = request.uri.queryParameters['error'];

    if (code != null && code.isNotEmpty) {
      _complete(code);
      _writePage(request.response, success: true);
    } else if (error != null && error.isNotEmpty) {
      _complete(null);
      _writePage(
        request.response,
        success: false,
        message: request.uri.queryParameters['error_description'] ?? error,
      );
    } else {
      _writePage(
        request.response,
        success: false,
        message:
            'Missing authorization code. Please close this page and '
            'try again in the terminal.',
        statusCode: 400,
      );
    }
  }

  void _complete(String? code) {
    final completer = _codeCompleter;
    if (completer != null && !completer.isCompleted) {
      completer.complete(code);
    }
    unawaited(close());
  }

  void _onDone() {
    final completer = _codeCompleter;
    if (completer != null && !completer.isCompleted) {
      completer.complete(null);
    }
  }

